607	        }
608	        (Some("csv"), "source") => &["csv"],
609	        (Some("plugin"), "source") => &["wasm"],
610	        (Some("cbor"), "source") => &["cbor"],
611	        (Some("json"), "source") => &["json"],
612	        (Some("toml"), "source") => &["toml"],
613	        (Some("xml"), "source") => &["xml"],
614	        (Some("yaml"), "source") => &["yml", "yaml"],
615	        (Some("bibliography"), "sources") => &["bib", "yml", "yaml"],
616	        (Some("bibliography"), "style") => &["csl"],
617	        (Some("cite"), "style") => &["csl"],
618	        (Some("raw"), "syntaxes") => &["sublime-syntax"],
