1034	/// See if the AST node is somewhere within a show rule applying to equations
1035	fn is_in_equation_show_rule(leaf: &LinkedNode<'_>) -> bool {
1036	    let mut node = leaf;
1037	    while let Some(parent) = node.parent() {
1038	        if let Some(expr) = parent.get().cast::<ast::Expr>()
1039	            && let ast::Expr::ShowRule(show) = expr
1040	            && let Some(ast::Expr::FieldAccess(field)) = show.selector()
1041	            && field.field().as_str() == "equation"
1042	        {
1043	            return true;
1044	        }
1045	        node = parent;
1046	    }
1047	    false
1048	}
