1215	    /// Add completions for labels and references.
1216	    fn label_completions(&mut self) {
1217	        let Some(output) = self.output else { return };
1218	        let (labels, split) = analyze_labels(output);
1219	
1220	        let head = &self.text[..self.from];
1221	        let at = head.ends_with('@');
1222	        let open = !at && !head.ends_with('<');
1223	        let close = !at && !self.after.starts_with('>');
1224	        let citation = !at && self.before_window(15).contains("cite");
1225	
1226	        let (skip, take) = if at {
1227	            (0, usize::MAX)
1228	        } else if citation {
1229	            (split, usize::MAX)
1230	        } else {
1231	            (0, split)
1232	        };
1233	
1234	        for (label, detail) in labels.into_iter().skip(skip).take(take) {
1235	            self.completions.push(Completion {
1236	                kind: CompletionKind::Label,
1237	                apply: (open || close).then(|| {
1238	                    eco_format!(
1239	                        "{}{}{}",
1240	                        if open { "<" } else { "" },
1241	                        label.resolve(),
1242	                        if close { ">" } else { "" }
1243	                    )
1244	                }),
1245	                label: label.resolve().as_str().into(),
1246	                detail,
1247	            });
1248	        }
1249	    }
