1272	    /// Add a completion for a specific value.
1273	    fn value_completion_full(
1274	        &mut self,
1275	        label: Option<EcoString>,
1276	        value: &Value,
1277	        parens: bool,
1278	        kind: Option<CompletionKind>,
1279	        detail: Option<&str>,
1280	    ) {
1281	        let at = label.as_deref().is_some_and(|field| !is_ident(field));
1282	        let label = label.unwrap_or_else(|| value.repr());
1283	
1284	        let detail = detail.map(Into::into).or_else(|| match value {
1285	            Value::Symbol(_) => None,
1286	            Value::Func(_) | Value::Type(_) => {
1287	                find_value_docs(self.world, value).map(|docs| docs.summary())
1288	            }
1289	            v => {
1290	                let repr = v.repr();
1291	                (repr.as_str() != label).then_some(repr)
1292	            }
1293	        });
1294	
1295	        let mut apply = None;
1296	        if parens
1297	            && matches!(value, Value::Func(_))
1298	            && !self.after.starts_with(['(', '['])
1299	        {
1300	            if let Value::Func(func) = value {
1301	                let bracket_mode = if self.leaf.mode_after() == Some(SyntaxMode::Math) {
1302	                    BracketMode::RoundWithin
1303	                } else {
1304	                    BracketMode::of(func)
1305	                };
1306	                apply = Some(match bracket_mode {
1307	                    BracketMode::RoundAfter => eco_format!("{label}()${{}}"),
1308	                    BracketMode::RoundWithin => eco_format!("{label}(${{}})"),
1309	                    BracketMode::RoundNewline => eco_format!("{label}(\n  ${{}}\n)"),
1310	                    BracketMode::SquareWithin => eco_format!("{label}[${{}}]"),
1311	                });
1312	            }
1313	        } else if at {
1314	            apply = Some(eco_format!("at(\"{label}\")"));
1315	        } else if label.starts_with('"')
1316	            && self.after.starts_with('"')
1317	            && let Some(trimmed) = label.strip_suffix('"')
1318	        {
1319	            apply = Some(trimmed.into());
1320	        }
1321	
1322	        self.completions.push(Completion {
1323	            kind: kind.unwrap_or_else(|| match value {
1324	                Value::Func(_) => CompletionKind::Func,
1325	                Value::Type(_) => CompletionKind::Type,
1326	                Value::Symbol(s) => CompletionKind::Symbol(s.get().into()),
1327	                _ => CompletionKind::Constant,
1328	            }),
1329	            label,
1330	            apply,
1331	            detail,
1332	        });
1333	    }
