1361	                    self.snippet_completion(
1362	                        "rgb()",
1363	                        "rgb(${r}, ${g}, ${b}, ${a})",
1364	                        "A custom RGBA color.",
1365	                    );
1366	                    self.snippet_completion(
1367	                        "cmyk()",
1368	                        "cmyk(${c}, ${m}, ${y}, ${k})",
1369	                        "A custom CMYK color.",
1370	                    );
1371	                    self.snippet_completion(
1372	                        "oklab()",
1373	                        "oklab(${l}, ${a}, ${b}, ${alpha})",
1374	                        "A custom Oklab color.",
1375	                    );
1376	                    self.snippet_completion(
1377	                        "oklch()",
1378	                        "oklch(${l}, ${chroma}, ${hue}, ${alpha})",
1379	                        "A custom Oklch color.",
1380	                    );
1381	                    self.snippet_completion(
1382	                        "color.linear-rgb()",
1383	                        "color.linear-rgb(${r}, ${g}, ${b}, ${a})",
1384	                        "A custom linear RGBA color.",
1385	                    );
1386	                    self.snippet_completion(
1387	                        "color.hsv()",
