1407	                        kind: CompletionKind::Syntax,
1408	                        label: ty.long_name().into(),
1409	                        apply: Some(eco_format!("${{{ty}}}")),
1410	                        detail: Some(eco_format!("A value of type {ty}.")),
1411	                    });
1412	                    self.scope_completions(false, |value| value.ty() == *ty);
