1515	    type Response = Option<(usize, Vec<Completion>)>;
1516	
1517	    trait ResponseExt {
1518	        fn completions(&self) -> &[Completion];
1519	        fn labels(&self) -> BTreeSet<&str>;
1520	        fn must_be_empty(&self) -> &Self;
1521	        fn must_include<'a>(&self, includes: impl IntoIterator<Item = &'a str>) -> &Self;
1522	        fn must_exclude<'a>(&self, excludes: impl IntoIterator<Item = &'a str>) -> &Self;
1523	        fn at(&self, label: &str) -> &Completion;
1524	    }
1525	
1526	    impl ResponseExt for Response {
1527	        fn completions(&self) -> &[Completion] {
1528	            match self {
1529	                Some((_, completions)) => completions.as_slice(),
1530	                None => &[],
1531	            }
1532	        }
1533	
1534	        fn labels(&self) -> BTreeSet<&str> {
1535	            self.completions().iter().map(|c| c.label.as_str()).collect()
1536	        }
1537	
1538	        #[track_caller]
1539	        fn must_be_empty(&self) -> &Self {
1540	            let labels = self.labels();
1541	            assert!(
1542	                labels.is_empty(),
1543	                "expected no suggestions (got {labels:?} instead)"
1544	            );
1545	            self
1546	        }
1547	
1548	        #[track_caller]
1549	        fn must_include<'a>(&self, includes: impl IntoIterator<Item = &'a str>) -> &Self {
1550	            let labels = self.labels();
1551	            for item in includes {
1552	                assert!(
1553	                    labels.contains(item),
1554	                    "{item:?} was not contained in {labels:?}",
1555	                );
1556	            }
1557	            self
1558	        }
1559	
1560	        #[track_caller]
1561	        fn must_exclude<'a>(&self, excludes: impl IntoIterator<Item = &'a str>) -> &Self {
1562	            let labels = self.labels();
1563	            for item in excludes {
1564	                assert!(
1565	                    !labels.contains(item),
1566	                    "{item:?} was wrongly contained in {labels:?}",
1567	                );
1568	            }
1569	            self
1570	        }
1571	
1572	        #[track_caller]
1573	        fn at(&self, label: &str) -> &Completion {
1574	            self.completions()
1575	                .iter()
1576	                .find(|c| c.label == label)
1577	                .unwrap_or_else(|| panic!("found no completion for {label:?}"))
1578	        }
1579	    }
1580	
1581	    trait CompletionExt {
1582	        fn must_apply_as<'a>(&self, apply: impl Into<Option<&'a str>>) -> &Self;
1583	        fn must_have_detail<'a>(&self, detail: impl Into<Option<&'a str>>) -> &Self;
1584	    }
1585	
1586	    impl CompletionExt for Completion {
1587	        #[track_caller]
1588	        fn must_apply_as<'a>(&self, apply: impl Into<Option<&'a str>>) -> &Self {
1589	            assert_eq!(self.apply.as_deref(), apply.into());
1590	            self
1591	        }
1592	
1593	        #[track_caller]
1594	        fn must_have_detail<'a>(&self, detail: impl Into<Option<&'a str>>) -> &Self {
1595	            assert_eq!(self.detail.as_deref(), detail.into());
1596	            self
1597	        }
1598	    }
