    /// Test what kind of brackets we autocomplete for function calls depending
    /// on the function and existing parens.
    #[test]
    fn test_autocomplete_bracket_mode() {
        test("#", 1).at("list").must_apply_as("list(${})");
        test("#", 1).at("linebreak").must_apply_as("linebreak()${}");
        test("#", 1).at("strong").must_apply_as("strong[${}]");
        test("#", 1).at("footnote").must_apply_as("footnote[${}]");
        test("#", 1).at("figure").must_apply_as("figure(\n  ${}\n)");
        test("#", 1).at("table").must_apply_as("table(\n  ${}\n)");
        test("#()", 1).at("list").must_apply_as(None);
        test("#[]", 1).at("strong").must_apply_as(None);
        test("$$", 1).at("overline").must_apply_as("overline(${})");
    }

    /// Test that we only complete positional parameters if they aren't
    /// already present.
    #[test]
    fn test_autocomplete_positional_param() {
        // No string given yet.
        test("#numbering()", -2).must_include(["string", "integer"]);
        // String is already given.
        test("#numbering(\"foo\", )", -2)
            .must_include(["integer"])
            .must_exclude(["string"]);
        // Integer is already given, but numbering is variadic.
        test("#numbering(\"foo\", 1, )", -2)
            .must_include(["integer"])
            .must_exclude(["string"]);
        // After argument list no completions.
        test("#numbering()", -1).must_exclude(["string"]);
    }

    /// Test that autocompletion for values of known type picks up nested
