    fn test_autocomplete_user_function_params() {
        let world = TestWorld::new("#import \"lib.typ\": *\n#foo()")
            .with_source("lib.typ", crate::tests::EXAMPLE_CLOSURE);
        let res = test(&world, -2);
        res.must_include(["forest", "tree"]);
